<template><view class="cards-page"><view class="nav"><text @tap="back">‹</text><text>银行卡管理</text><view/></view><view class="body"><view class="count">已绑定 {{ wallet.cards.length }} 张银行卡 <text>（最多绑定5张）</text></view><view v-for="card in wallet.cards" :key="card.id" class="bank-card" :style="{background: `linear-gradient(135deg, ${card.color}, #1e2745)`}" @tap="cardActions(card)"><text class="bank-name">{{card.bank}}</text><text class="card-type">{{card.type}}</text><text class="card-number">••••  ••••  ••••  {{card.tail}}</text><text class="card-owner">张*希</text></view><button class="add" :disabled="wallet.cards.length>=5" @tap="addCard">＋ 添加银行卡</button></view></view></template>
<script setup>import{onMounted}from'vue';import{enforcePortal}from'../../core/route-guard';import{wallet}from'../../services/wallet';onMounted(()=>enforcePortal('agent'));function back(){uni.navigateBack()}function addCard(){if(wallet.cards.length>=5){uni.showToast({title:'最多支持绑定5张银行卡',icon:'none'});return}uni.navigateTo({url:'/pages/agent/add-bank-card'})}function cardActions(card){uni.showActionSheet({itemList:['解除绑定'],success:()=>uni.showModal({title:'解除绑定',content:`确认解绑${card.bank}（尾号${card.tail}）吗？`,success:r=>{if(r.confirm){const i=wallet.cards.findIndex(x=>x.id===card.id);wallet.cards.splice(i,1)}}})})}</script>
<style lang="scss" scoped>.cards-page{min-height:100vh;background:#f7f8fc;color:#28334c}.nav{display:flex;justify-content:space-between;align-items:center;height:calc(102rpx + env(safe-area-inset-top));padding:env(safe-area-inset-top) 32rpx 0;background:#fff;box-sizing:border-box;font-size:30rpx;font-weight:720}.nav text:first-child{width:60rpx;color:#5966f3;font-size:60rpx;line-height:1}.nav view{width:60rpx}.body{padding:36rpx 34rpx}.count{display:block;margin-bottom:25rpx;color:#7d889b;font-size:23rpx}.bank-card{position:relative;height:268rpx;margin-bottom:22rpx;padding:31rpx;border-radius:28rpx;color:#fff;box-shadow:0 17rpx 36rpx rgba(25,36,75,.18);box-sizing:border-box}.bank-name,.card-type,.card-number,.card-owner{display:block}.bank-name{font-size:32rpx;font-weight:750}.card-type{margin-top:8rpx;color:rgba(255,255,255,.72);font-size:20rpx}.card-number{margin-top:68rpx;font-size:32rpx;letter-spacing:3rpx}.card-owner{position:absolute;bottom:28rpx;color:rgba(255,255,255,.75);font-size:21rpx}.add{width:100%;margin-top:17rpx;border:1rpx solid #cdd3e0;border-radius:16rpx;background:#fff;color:#5966f3;font-size:27rpx;line-height:86rpx}.add[disabled]{color:#a5acba}.add::after{border:0}</style>
